using System;
using System.Linq;
using System.Collections.Generic;
using TicketingSystemFightNight.Models;

// Kreiramo model i ispunjavamo s podacima (bar 3 glavna objekta):
var venue1 = new Venue { Id = 1, Name = "Arena Zagreb", City = "Zagreb", Address = "Trg Krešimira Ćosića 11", Capacity = 15000, OpenDate = new DateTime(2008, 12, 24) };
var venue2 = new Venue { Id = 2, Name = "Arena Split", City = "Split", Address = "Ulica Domovinskog rata 30", Capacity = 12000, OpenDate = new DateTime(2011, 3, 17) };
var venue3 = new Venue { Id = 3, Name = "Arena Rijeka", City = "Rijeka", Address = "M. Tita 6", Capacity = 10000, OpenDate = new DateTime(2015, 6, 5) };

var fighters = new List<Fighter>
{
    new Fighter { Id = 1, FirstName = "Ivan", LastName = "Horvat", Nickname = "Tornado", Country = "HR", WeightClass = FightWeightClass.Middleweight, Wins = 12, Losses = 2, Draws = 1 },
    new Fighter { Id = 2, FirstName = "Marko", LastName = "Kovač", Nickname = "Smash", Country = "HR", WeightClass = FightWeightClass.Middleweight, Wins = 11, Losses = 3, Draws = 0 },
    new Fighter { Id = 3, FirstName = "Luka", LastName = "Babić", Nickname = "Razor", Country = "SI", WeightClass = FightWeightClass.Lightweight, Wins = 15, Losses = 0, Draws = 0 },
    new Fighter { Id = 4, FirstName = "Tomislav", LastName = "Ćosić", Nickname = "Phantom", Country = "HR", WeightClass = FightWeightClass.Welterweight, Wins = 9, Losses = 4, Draws = 1 },
    new Fighter { Id = 5, FirstName = "Matej", LastName = "Jurić", Nickname = "Flash", Country = "BA", WeightClass = FightWeightClass.Heavyweight, Wins = 8, Losses = 2, Draws = 0 },
    new Fighter { Id = 6, FirstName = "Dario", LastName = "Perić", Nickname = "Viper", Country = "HR", WeightClass = FightWeightClass.Featherweight, Wins = 18, Losses = 1, Draws = 0 },
    new Fighter { Id = 7, FirstName = "Nikola", LastName = "Matić", Nickname = "Titan", Country = "SRB", WeightClass = FightWeightClass.Heavyweight, Wins = 14, Losses = 5, Draws = 0 },
    new Fighter { Id = 8, FirstName = "Filip", LastName = "Đurić", Nickname = "Blitz", Country = "HR", WeightClass = FightWeightClass.Welterweight, Wins = 10, Losses = 5, Draws = 1 }
};

var events = new List<FightEvent>
{
    new FightEvent { Id = 1, Title = "Fight Night Zagreb", Date = DateTime.Today.AddDays(25), Venue = venue1, BasePrice = 150M, IsPublic = true },
    new FightEvent { Id = 2, Title = "Split Power Clash", Date = DateTime.Today.AddDays(40), Venue = venue2, BasePrice = 130M, IsPublic = true },
    new FightEvent { Id = 3, Title = "Rijeka Rumble", Date = DateTime.Today.AddDays(60), Venue = venue3, BasePrice = 120M, IsPublic = true }
};

venue1.Events.Add(events[0]);
venue2.Events.Add(events[1]);
venue3.Events.Add(events[2]);

var matches = new List<Match>
{
    new Match { Id = 1, Event = events[0], StartTime = events[0].Date.AddHours(19), RedCorner = fighters[0], BlueCorner = fighters[1], Title = "Middleweight Championship", Rounds = 5, IsMainEvent = true, Result = "W by decision" },
    new Match { Id = 2, Event = events[0], StartTime = events[0].Date.AddHours(17), RedCorner = fighters[2], BlueCorner = fighters[3], Title = "Welterweight Duel", Rounds = 3, IsMainEvent = false, Result = "W by KO" },
    new Match { Id = 3, Event = events[1], StartTime = events[1].Date.AddHours(19), RedCorner = fighters[4], BlueCorner = fighters[6], Title = "Heavyweight Battle", Rounds = 5, IsMainEvent = true, Result = "W by TKO" },
    new Match { Id = 4, Event = events[1], StartTime = events[1].Date.AddHours(17), RedCorner = fighters[5], BlueCorner = fighters[7], Title = "Featherweight Clash", Rounds = 3, IsMainEvent = false, Result = "W by submission" },
    new Match { Id = 5, Event = events[2], StartTime = events[2].Date.AddHours(19), RedCorner = fighters[1], BlueCorner = fighters[4], Title = "Openweight Fight", Rounds = 5, IsMainEvent = true, Result = "W by decision" }
};

foreach (var m in matches)
{
    events.First(e => e.Id == m.Event.Id).Matches.Add(m);
    m.RedCorner.Matches.Add(m);
    m.BlueCorner.Matches.Add(m);
}

var seats = new List<Seat>();
int seatId = 1;
foreach (var v in new[] { venue1, venue2, venue3 })
{
    for (int section = 1; section <= 3; section++)
    {
        for (int row = 1; row <= 5; row++)
        {
            for (int num = 1; num <= 10; num++)
            {
                seats.Add(new Seat { Id = seatId++, Section = $"S{section}", Row = row, Number = num, IsAccessible = row == 1, PremiumFactor = section switch { 1 => 2.0M, 2 => 1.5M, _ => 1.0M } });
            }
        }
    }
}

var rnd = new Random(42);
var tickets = new List<Ticket>();
int ticketId = 1;
foreach (var fightEvent in events)
{
    var eventSeats = seats.Skip((fightEvent.Id - 1) * 150).Take(150).ToList();
    foreach (var seat in eventSeats)
    {
        var cat = (TicketCategory)rnd.Next(0, 4);
        var price = fightEvent.BasePrice * seat.PremiumFactor;
        tickets.Add(new Ticket
        {
            Id = ticketId++,
            Code = $"{fightEvent.Id:00}-{seat.Section}-{seat.Row:00}-{seat.Number:00}",
            Category = cat,
            Price = price,
            Seat = seat,
            Event = fightEvent,
            Match = fightEvent.Matches.FirstOrDefault(),
            IsSold = false
        });
        fightEvent.Tickets.Add(tickets.Last());
        seat.Tickets.Add(tickets.Last());
    }
}

var customers = new List<Customer>
{
    new Customer { Id = 1, FirstName = "Ana", LastName = "Marin", Email = "ana.marin@example.com", Phone = "+385912345678", DateOfBirth = new DateTime(1995, 3, 14) },
    new Customer { Id = 2, FirstName = "Ivan", LastName = "Vladić", Email = "ivan.vladic@example.com", Phone = "+385912345679", DateOfBirth = new DateTime(1989, 7, 22) },
    new Customer { Id = 3, FirstName = "Petra", LastName = "Kranjčić", Email = "petra.kranjcic@example.com", Phone = "+385912345680", DateOfBirth = new DateTime(2000, 11, 2) }
};

var reservation1 = new Reservation { Id = 1, Customer = customers[0], CreatedAt = DateTime.Now, IsPaid = true };
var reservation2 = new Reservation { Id = 2, Customer = customers[1], CreatedAt = DateTime.Now, IsPaid = false };
var reservation3 = new Reservation { Id = 3, Customer = customers[2], CreatedAt = DateTime.Now, IsPaid = true };

customers[0].Reservations.Add(reservation1);
customers[1].Reservations.Add(reservation2);
customers[2].Reservations.Add(reservation3);

var chosenTickets = tickets.Where(t => t.Event.Id == 1).Take(4).ToList();
foreach (var t in chosenTickets)
{
    t.IsSold = true;
    t.Reservation = reservation1;
    reservation1.Tickets.Add(t);
}

chosenTickets = tickets.Where(t => t.Event.Id == 2).Skip(3).Take(3).ToList();
foreach (var t in chosenTickets)
{
    t.IsSold = true;
    t.Reservation = reservation2;
    reservation2.Tickets.Add(t);
}

chosenTickets = tickets.Where(t => t.Event.Id == 3).Skip(6).Take(2).ToList();
foreach (var t in chosenTickets)
{
    t.IsSold = true;
    t.Reservation = reservation3;
    reservation3.Tickets.Add(t);
}

// LINQ upiti
Console.WriteLine("\n=== LINQ upiti za projekt borilačkih eventa ===\n");

// 1. Svi budući eventi
var upcomingEvents = from e in events
                     where e.Date > DateTime.Today
                     orderby e.Date
                     select e;
Console.WriteLine("Budući eventi:");
foreach (var ev in upcomingEvents)
{
    Console.WriteLine($"- {ev.Title} ({ev.Date:dd.MM.yyyy}) u {ev.Venue.City}");
}

// 2. Najbolji fighteri (najviše pobjeda)
var topFighters = fighters.OrderByDescending(f => f.Wins).Take(3);
Console.WriteLine("\nTop 3 fightera prema pobjedama:");
foreach (var f in topFighters)
{
    Console.WriteLine($"- {f.Nickname} ({f.FirstName} {f.LastName}), Wins: {f.Wins}, Losses: {f.Losses}");
}

// 3. Dostupni (neosvojeni) VIP ulaznice za prvi event
var availableVip = events[0].Tickets.Where(t => t.Category == TicketCategory.VIP && !t.IsSold);
Console.WriteLine($"\nDostupne VIP ulaznice za {events[0].Title}: {availableVip.Count()}");

// 4. Prihodi po eventu
var revenuePerEvent = events.Select(e => new
{
    e.Title,
    SoldRevenue = e.Tickets.Where(t => t.IsSold).Sum(t => t.Price),
    SoldTickets = e.Tickets.Count(t => t.IsSold)
});
Console.WriteLine("\nPrihodi po eventu:");
foreach (var r in revenuePerEvent)
{
    Console.WriteLine($"- {r.Title}: {r.SoldRevenue:C} (prodano ulaznica: {r.SoldTickets})");
}

// 5. Kupci s plaćenim rezervacijama
var paidCustomers = from c in customers
                    where c.Reservations.Any(r => r.IsPaid)
                    select new { c.FirstName, c.LastName, Count = c.Reservations.Count(r => r.IsPaid) };
Console.WriteLine("\nKupci s barem jednom plaćenom rezervacijom:");
foreach (var c in paidCustomers)
{
    Console.WriteLine($"- {c.FirstName} {c.LastName} ({c.Count})");
}

// 6. Eventi s više od 120 prodanih ulaznica
var busyEvents = events.Where(e => e.Tickets.Count(t => t.IsSold) > 120);
Console.WriteLine("\nCiljani eventi s više od 120 prodanih ulaznica:");
Console.WriteLine(busyEvents.Any() ? string.Join("; ", busyEvents.Select(e => e.Title)) : "(nema)");

Console.WriteLine("\nGotovo. Model je postavljen i LINQ upiti rade.

